import openpyxl
from collections import Counter
from pathlib import Path

wb = openpyxl.load_workbook('/root/copy_of_capacity_sheet.xlsx', data_only=True)
ws = wb['Weld']

# Find candidate header rows: count of integer-like week values between 1..60
row_scores = []
for r in range(1, min(ws.max_row, 250) + 1):
    weeks = []
    for c in range(1, ws.max_column + 1):
        v = ws.cell(r,c).value
        if isinstance(v,(int,float)) and not isinstance(v,bool):
            if float(v).is_integer():
                iv=int(v)
                if 1<=iv<=60:
                    weeks.append(iv)
    if weeks:
        row_scores.append((len(set(weeks)), len(weeks), r, sorted(set(weeks))[:10], sorted(set(weeks))[-10:]))

row_scores.sort(reverse=True)
print('Top 15 rows by distinct week-like integers (distinct_count, total_count, row, first10, last10):')
for item in row_scores[:15]:
    print(item)

# Also look for string headers containing 'Week'
rows_with_weekword=[]
for r in range(1, min(ws.max_row, 250)+1):
    for c in range(1, min(ws.max_column, 60)+1):
        v=ws.cell(r,c).value
        if isinstance(v,str) and 'week' in v.lower():
            rows_with_weekword.append((r,c,v))

print('\nCells containing "week" (first 30):')
for x in rows_with_weekword[:30]:
    print(x)

# Print a snapshot of the top candidate row's first 40 columns
if row_scores:
    _,_,best_row,_,_=row_scores[0]
    print(f"\nSnapshot of best_row={best_row} (first 50 columns):")
    vals=[]
    for c in range(1,51):
        v=ws.cell(best_row,c).value
        if v is None:
            vals.append('')
        else:
            vals.append(str(v))
    for i in range(0,50,10):
        print(f"C{i+1:02d}-C{i+10:02d}:", vals[i:i+10])

# Locate where week 4 appears in sheet
positions=[]
for r in range(1, min(ws.max_row, 400)+1):
    for c in range(1, min(ws.max_column, 200)+1):
        v=ws.cell(r,c).value
        if v==4 or v=='4':
            positions.append((r,c,v))

print('\nPositions with value exactly 4 (first 30):')
for p in positions[:30]:
    print(p)
print('Total positions with 4:', len(positions))
